using System;
using CSharpAuthor.Profiles;
using Xunit;

namespace CSharpAuthor.Tests.ProfileTests;

/// <summary>
/// Where <see cref="DownlevelCommentPlacement.FileHeader"/> puts its notes in a whole file.
/// </summary>
/// <remarks>
/// Analyzers, StyleCop and the IDE read the first comment of a file to decide whether it is
/// generated. A note written above <c>// &lt;auto-generated/&gt;</c> makes them report on it.
/// </remarks>
public class DownlevelHeaderPlacementTests
{
    private const string InitNote =
        "// DOWNLEVEL: Name: 'init' unavailable below C#9 — emitted as a settable property, immutability lost";

    // ShortName records the file and serializes it in Output; Global streams it as it is written.
    // The header boundary is tracked separately on the two paths.
    [Theory]
    [InlineData(PolyfillMode.None, TypeOutputMode.ShortName)]
    [InlineData(PolyfillMode.Always, TypeOutputMode.ShortName)]
    [InlineData(PolyfillMode.None, TypeOutputMode.Global)]
    [InlineData(PolyfillMode.Always, TypeOutputMode.Global)]
    public void TheAutoGeneratedMarkerStaysOnLineOne(PolyfillMode polyfills, TypeOutputMode typeMode)
    {
        var profile = EmitProfile.Conservative.With(p =>
        {
            p.DownlevelComments = DownlevelCommentPlacement.FileHeader;
            p.Polyfills = polyfills;
            p.TypeMode = typeMode;
        });

        var lines = Lines(ProfileEmitter.Emit(GeneratedFile(), profile).Code);

        Assert.Equal("// <auto-generated/>", lines[0]);
        Assert.Equal(InitNote, lines[1]);
    }

    [Fact]
    public void TheNotesStayAboveTheUsings()
    {
        var profile = EmitProfile.Conservative.With(p =>
            p.DownlevelComments = DownlevelCommentPlacement.FileHeader);

        var code = ProfileEmitter.Emit(GeneratedFile(), profile).Code;

        var note = code.IndexOf(InitNote, StringComparison.Ordinal);
        var firstUsing = code.IndexOf("using ", StringComparison.Ordinal);

        Assert.True(note >= 0, code);
        Assert.True(firstUsing > note, code);
    }

    private static CSharpFileDefinition GeneratedFile()
    {
        var file = new CSharpFileDefinition("Gen");

        file.AddAutoGeneratedHeader();

        var widget = file.AddClass("Widget");

        widget.Modifiers = ComponentModifier.Public;

        var name = widget.AddProperty(typeof(string), "Name");

        name.Set!.IsInit = true;

        widget.AddProperty(typeof(System.Text.StringBuilder), "Buffer");

        return file;
    }

    private static string[] Lines(string code) =>
        code.Replace("\r\n", "\n").Split('\n');
}
